package net.civeira.phylax.feature.identity.user.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.identity.user.domain.UserApprovalStatusOptions;

class ApprovalStatusVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property approval status of user ")
  void test_approval_status_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> ApprovalStatusVO.tryFrom("_UNVERIFIED_"));
    Assertions.assertEquals(UserApprovalStatusOptions.UNVERIFIED,
        ApprovalStatusVO.tryFrom("UNVERIFIED").getApprovalStatus().orElse(null));
    Assertions.assertFalse(ApprovalStatusVO.nullValue().getApprovalStatus().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ApprovalStatusVO.tryFrom(null).getApprovalStatus().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(UserApprovalStatusOptions.UNVERIFIED, ApprovalStatusVO
        .from(UserApprovalStatusOptions.UNVERIFIED).getApprovalStatus().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ApprovalStatusVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + UserApprovalStatusOptions.UNVERIFIED + "]",
        ApprovalStatusVO.from(UserApprovalStatusOptions.UNVERIFIED).toString());
  }
}
